HAL_StatusTypeDef HAL_UARTEx_ReceiveToIdle_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  HAL_StatusTypeDef status;

  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    /* Set Reception type to reception till IDLE Event*/
    huart->ReceptionType = HAL_UART_RECEPTION_TOIDLE;
    huart->RxEventType = HAL_UART_RXEVENT_TC;

    /* Skip the call to UART_Start_Receive_IT as it may have hardware dependencies */
    /* Instead, set up the receive state directly */
    huart->pRxBuffPtr = pData;
    huart->RxXferSize = Size;
    huart->RxXferCount = Size;
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;

    status = HAL_OK;

    /* Check Rx process has been successfully started */
    if (status == HAL_OK)
    {
      if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
      {
        /* Skip hardware-specific operations */
        /* Original: __HAL_UART_CLEAR_IDLEFLAG(huart); */
        /* Original: ATOMIC_SET_BIT(huart->Instance->CR1, USART_CR1_IDLEIE); */

        /* In emulation, we can simulate receiving data immediately */
        /* Use HAL_BE_In to read data from stdin */
        int received = HAL_BE_In(pData, Size);
        if (received > 0)
        {
          huart->RxXferCount = Size - received;
          if (huart->RxXferCount == 0)
          {
            /* Reception complete */
            huart->RxState = HAL_UART_STATE_READY;

            /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback to avoid loops */
            /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxCpltCallback != NULL)
            {
              huart->RxCpltCallback(huart);
            }
#else
            HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
        }
        else
        {
          /* Error receiving data */
          status = HAL_ERROR;
          huart->RxState = HAL_UART_STATE_READY;
        }
      }
      else
      {
        /* In case of errors already pending when reception is started,
           Interrupts may have already been raised and lead to reception abortion.
           (Overrun error for instance).
           In such case Reception Type has been reset to HAL_UART_RECEPTION_STANDARD. */
        status = HAL_ERROR;
        huart->RxState = HAL_UART_STATE_READY;
      }
    }

    return status;
  }
  else
  {
    return HAL_BUSY;
  }
}
